<?php if (!isset($docs)) { http_response_code(404); exit; } $sentList=function_exists('last_sent') ? last_sent(array_column($docs,'id')) : [];
$docRisk=fn(array $d)=>(int)$d['paid']>0 ? number($d).' with '.json_decode($d['company_snapshot'],true)['currency'].' '.money((int)$d['paid']).' in payments' : ''; ?>
<div class="table-wrap"><table><thead><tr><?php if (!empty($pick)): ?><th class="pick"><input type="checkbox" class="pick-all" aria-label="Tick every document on this page"></th><?php endif ?><th>Document</th><th>Customer</th><th>Date</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach ($docs as $d): $customer=json_decode($d['customer_snapshot'],true); $company=json_decode($d['company_snapshot'],true); $status=$d['kind']==='quotation'?'Proforma':((int)$d['paid']>=(int)$d['total']?'Paid':($d['due_date']<date('Y-m-d')?'Overdue':((int)$d['paid']>0?'Part paid':'Unpaid'))); $sent=$sentList[(int)$d['id']]??null; ?>
<tr><?php if (!empty($pick)): ?><td class="pick"><input type="checkbox" name="ids[]" value="<?=$d['id']?>" class="pick-one" aria-label="Tick <?=e(number($d))?>" data-label="<?=e(number($d))?>" data-risk="<?=e($docRisk($d))?>"></td><?php endif ?><td><a href="index.php?page=view&id=<?=$d['id']?>"><?=e(number($d))?></a><small>by <?=e(user_name((int)$d['created_by']))?></small></td><td><?=e($customer['name'])?><?php if (!empty($d['assigned_to'])): ?><small>Staff: <?=e($d['assigned_to'])?></small><?php endif ?></td><td><?=e($d['document_date'])?></td><td><?=e($company['currency'])?> <?=money((int)$d['total'])?></td><td><span class="badge"><?=e($status)?></span><?php if ($sent): ?><small class="<?=$sent['mail_status']==='accepted'?'sent-ok':'sent-failed'?>"><?=$sent['mail_status']==='accepted'?'✓ Sent '.e($sent['sent_at']->format('j M')):($sent['mail_status']==='failed'?'Email failed':'Email not confirmed')?></small><?php else: ?><small>Not emailed yet</small><?php endif ?></td><td class="nowrap"><a href="index.php?page=view&id=<?=$d['id']?>">View</a><?php if ((int)$d['paid']===0): ?> · <a href="index.php?page=new&edit=<?=$d['id']?>">Edit</a><?php endif ?><?php if (!empty($pick)): ?> · <button type="submit" name="only" value="<?=$d['id']?>" class="link-button danger-text" data-label="<?=e(number($d))?>" data-risk="<?=e($docRisk($d))?>">Delete</button><?php endif ?></td></tr>
<?php endforeach ?><?php if (!$docs): ?><tr><td colspan="<?=empty($pick)?6:7?>">No documents yet. Create your first Proforma or Tax Invoice.</td></tr><?php endif ?></tbody></table></div>
